-- Steckbrief und 40 gruene Instanzen (Status draft, Pool session). Pruefmaschine: 40 gruen,
-- 1 rot (verworfen). Blindloeser: {"geloest": 10, "abweichend": [], "bestanden": true}.
-- Vorschau: docs/reihe1/A/bauformen/QW-1.json. Aendert sich der Steckbrief, steigt die Version (Trigger); die
-- Instanzen tragen die neue Version, die alten bleiben fuer die Historie. Der Steckbrief enthaelt den Hash des
-- Generators: aendert sich der Generator, steigt die Version ebenfalls.
--
-- Pruefabfrage: select count(*) from tasks t join bauformen b on b.id = t.bauform_id
--                where b.schluessel = 'QW-1' and t.bauform_version = b.version;   → 40
do $$ begin perform set_config('edvance.bauform_export', '1', true); end $$;
insert into public.bauformen (schluessel, skill_key, kernidee_key, format, rollen, steckbrief, generator_pfad, status,
                              pruefprotokoll, blindloeser, verdacht)
values ('QW-1', 'zahl_wurzel_quadrat', null, 'zahl', '{warmup,uebung,home}'::text[],
        '{"text": "Berechne {aufgabe}.", "stufen": {"1": "n², n von 3 bis 12", "2": "√m, m Quadratzahl von 9 bis 225", "3": "(−n)², n von 3 bis 20"}, "fehlbilder": [{"key": "qf_quadrat_als_verdopplung", "regel": "n² als 2·n", "gilt_fuer_stufen": [1, 3], "rueckmeldung": "Quadrieren heißt: die Zahl mit sich selbst malnehmen, nicht mit 2."}, {"key": "qf_wurzel_als_haelfte", "regel": "√m als m/2", "gilt_fuer_stufen": [2], "rueckmeldung": "Die Wurzel ist nicht die Hälfte. Welche Zahl mal sich selbst ergibt die Zahl?"}, {"key": "qf_quadrat_negativ", "regel": "(−n)² = −n²", "gilt_fuer_stufen": [3], "rueckmeldung": "Minus mal Minus ergibt Plus. Ein Quadrat ist nie negativ."}], "hinweise": ["{frage_hinweis}", "{strategie}", "{schritt}"], "loesungsweg": ["{aufgabe}", "= {rechnung}", "= {ergebnis}"], "warum": null, "kontext": null, "figur": null, "zeit_sek": 30, "kann_entfallen": false, "generator_hash": "278078fe6672"}'::jsonb, 'scripts/bauformen/bauformen/qw_1.py', 'zur_pruefung',
        '{"gruen": 40, "rot": 1, "rot_anteil": 0.024, "gruende": {"7": 1}, "verdacht": null, "lauf_am": "20261028144751"}'::jsonb, '{"geloest": 10, "abweichend": [], "anteil": 0.0, "bestanden": true, "antworten": {"1": "100", "2": "400", "3": "36", "4": "7", "5": "16", "6": "121", "7": "81", "8": "169", "9": "9", "10": "6"}}'::jsonb, null)
on conflict (schluessel) do update
   set skill_key = excluded.skill_key, kernidee_key = excluded.kernidee_key, format = excluded.format,
       rollen = excluded.rollen, steckbrief = excluded.steckbrief, generator_pfad = excluded.generator_pfad,
       pruefprotokoll = excluded.pruefprotokoll, blindloeser = excluded.blindloeser, verdacht = excluded.verdacht,
       -- Lenas Entscheidung bleibt, solange sich nichts aendert; eine neue Version oeffnet der Trigger.
       status = case when excluded.verdacht is not null then 'entwurf'
                     when bauformen.status = 'entwurf' then 'zur_pruefung'
                     else bauformen.status end;

